namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications = [];
    private int _nextId = 1;
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        var now = DateTime.UtcNow;
        _notifications.Add(new(_nextId++, "Welcome to the app!", now.AddMinutes(-10)));
        _notifications.Add(new(_nextId++, "Your profile was updated.", now.AddMinutes(-5)));
        _notifications.Add(new(_nextId++, "New feature available: dark mode.", now.AddMinutes(-2)));

        // Simulate new notifications arriving over time
        _ = GenerateNotificationsAsync();
    }

    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    public List<Notification> GetSince(DateTime since)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Timestamp > since).ToList();
        }
    }

    private async Task GenerateNotificationsAsync()
    {
        var messages = new[]
        {
            "You have a new follower.",
            "Someone liked your post.",
            "System maintenance scheduled.",
            "Your export is ready.",
            "New comment on your article.",
            "Payment received.",
            "Security alert: new login detected.",
        };

        var rng = new Random();
        while (true)
        {
            await Task.Delay(TimeSpan.FromSeconds(rng.Next(4, 10)));
            lock (_lock)
            {
                var msg = messages[rng.Next(messages.Length)];
                _notifications.Add(new(_nextId++, msg, DateTime.UtcNow));
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = [];
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    protected override void OnInitialized()
    {
        // Runs during prerender AND when the component becomes interactive.
        // Load initial data so it appears in the server-rendered HTML.
        _notifications = NotificationSvc.GetAll();
        _lastCheck = _notifications.Count > 0
            ? _notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires when the component is live/interactive,
            // never during static SSR prerender. Safe to start polling here.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            var newItems = NotificationSvc.GetSince(_lastCheck);
            if (newItems.Count > 0)
            {
                _notifications.AddRange(newItems);
                _lastCheck = newItems.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

